import Foundation
import NLLBNative
import Testing

private let marianFolder = ProcessInfo.processInfo.environment["EARMARK_MARIAN_MODEL_DIR"]
private let opusRoot = ProcessInfo.processInfo.environment["EARMARK_OPUS_MODEL_ROOT"]

/// Goldens generated by CTranslate2 4.6.0 / SentencePiece 0.2.1 with the
/// pinned gaudi/opus-mt-en-de-ctranslate2 checkpoint in the research inventory.
/// These catch missing source EOS and accidental reuse of NLLB language tags.
@Suite("Marian native parity", .serialized, .enabled(if: marianFolder != nil))
struct MarianNativeTests {
    @Test func matchesPinnedReference() throws {
        let model = try NativeNLLBModel(
            folder: URL(fileURLWithPath: #require(marianFolder)), profile: .marian)
        #expect(try model.translate("The meeting starts tomorrow morning.", source: "en", target: "de") == "Das Treffen beginnt morgen früh.")
        #expect(try model.translate("Hello world.", source: "en", target: "de") == "Hallo Welt.")
    }

    @Test func refusesOversizedInputRatherThanTruncating() throws {
        let model = try NativeNLLBModel(
            folder: URL(fileURLWithPath: #require(marianFolder)), profile: .marian)
        #expect(throws: NativeNLLBError.self) {
            try model.translate(String(repeating: "meeting ", count: 600), source: "en", target: "de")
        }
    }
}

@Suite("Six OPUS checkpoint recipes", .serialized, .enabled(if: opusRoot != nil))
struct OPUSNativeRecipesTests {
    private struct Reference: Decodable {
        struct Row: Decodable {
            let pair: String
            let source: String
            let target: String
            let text: String
            let translation: String
            let sourcePieces: [String]
        }
        let rows: [Row]
    }

    @Test func eachDirectionMatchesItsOwnTokenizerAndNativeReference() throws {
        let fixture = try #require(Bundle.module.url(forResource: "opus-parity", withExtension: "json", subdirectory: "Fixtures"))
        let reference = try JSONDecoder().decode(Reference.self, from: Data(contentsOf: fixture))
        let root = URL(fileURLWithPath: try #require(opusRoot))
        for row in reference.rows {
            let model = try NativeNLLBModel(folder: root.appendingPathComponent("opus-" + row.pair), profile: .marian)
            #expect(try model.tokens(for: row.text) + ["</s>"] == row.sourcePieces)
            #expect(try model.translate(row.text, source: row.source, target: row.target) == row.translation)
        }
    }
}

@Suite("OPUS authored semantic cases", .serialized, .enabled(if: opusRoot != nil))
struct OPUSSemanticNativeTests {
    private struct Fixture: Decodable {
        struct Row: Decodable {
            struct Case: Decodable {
                let text: String
                let requiredWordGroups: [[String]]?
                let requiredIdentifier: String?
            }
            let pair: String
            let source: String
            let target: String
            let cases: [Case]
        }
        let rows: [Row]
    }

    @Test func retainsNamesNumbersIdentifiersAndNegation() throws {
        let fixture = try #require(Bundle.module.url(forResource: "opus-semantic-cases", withExtension: "json", subdirectory: "Fixtures"))
        let cases = try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: fixture))
        let root = URL(fileURLWithPath: try #require(opusRoot))
        for row in cases.rows {
            let model = try NativeNLLBModel(folder: root.appendingPathComponent("opus-" + row.pair), profile: .marian)
            for example in row.cases {
                let text = try model.translate(example.text, source: row.source, target: row.target)
                print("OPUS semantic \(row.pair): \(text)")
                let normalized = text.lowercased().replacingOccurrences(of: "’", with: "'")
                let words = Set(normalized.split { !$0.isLetter && !$0.isNumber && $0 != "'" }.map(String.init))
                for alternatives in example.requiredWordGroups ?? [] {
                    #expect(alternatives.contains { words.contains($0) }, "\(row.pair) lost a required semantic marker: \(alternatives)")
                }
                if let identifier = example.requiredIdentifier {
                    let compact = String(normalized.unicodeScalars.filter { CharacterSet.alphanumerics.contains($0) })
                    #expect(compact.contains(identifier), "\(row.pair) changed the identifier")
                }
            }
        }
    }
}
